mapper.select:
SELECT 
FROM iam_session
WHERE 1 = 1

    AND (login_at < #{afterLoginAt}
         OR (login_at = #{afterLoginAt} AND session_id < #{afterSessionId}))


    AND user_id = #{userId}


    AND client_type = #{clientType}


    AND revoked_at IS NULL
    AND expires_at > CURRENT_TIMESTAMP(6)


    AND (revoked_at IS NOT NULL OR expires_at <= CURRENT_TIMESTAMP(6))

ORDER BY login_at DESC, session_id DESC
LIMIT #{limit}

mapper.update:
UPDATE iam_session
SET last_seen_at = #{lastSeenAt}
WHERE session_id = #{sessionId}
  AND revoked_at IS NULL
  AND expires_at > #{lastSeenAt}
